create extension if not exists pgcrypto;

create table if not exists public.users (
  id uuid primary key references auth.users(id) on delete cascade,
  email text unique not null, name text not null, role text not null default 'TEAM_MEMBER' check (role in ('TEAM_MEMBER','MANAGER','ADMIN','QC')),
  active boolean not null default true, created_at timestamptz not null default now()
);
create table if not exists public.platforms (id uuid primary key default gen_random_uuid(), name text not null, code text unique not null, active boolean default true);
create table if not exists public.warehouses (id uuid primary key default gen_random_uuid(), name text not null, code text unique not null, city text not null, state text not null, active boolean default true);
create table if not exists public.skus (id uuid primary key default gen_random_uuid(), code text unique not null, name text not null, active boolean default true);
create table if not exists public.warehouse_sku_policies (id uuid primary key default gen_random_uuid(), warehouse_id uuid not null references warehouses(id), sku_id uuid not null references skus(id), threshold integer not null default 0, unique(warehouse_id,sku_id));
create table if not exists public.inventory_balances (id uuid primary key default gen_random_uuid(), warehouse_id uuid not null references warehouses(id), sku_id uuid not null references skus(id), physical integer not null default 0, blocked integer not null default 0, in_transit integer not null default 0, unique(warehouse_id,sku_id));
create table if not exists public.destination_mappings (id uuid primary key default gen_random_uuid(), platform_id uuid not null references platforms(id), destination text not null, fc_code text, city text, state text, warehouse_id uuid not null references warehouses(id), active boolean default true);
create table if not exists public.route_estimates (id uuid primary key default gen_random_uuid(), warehouse_id uuid not null references warehouses(id), destination text not null, transit_hours integer not null, cost numeric not null, active boolean default true);
create table if not exists public.purchase_orders (id uuid primary key default gen_random_uuid(), platform_id uuid not null references platforms(id), external_id text not null, po_date timestamptz not null, deadline timestamptz, destination text not null, customer text, total_value numeric not null default 0, status text not null default 'UPLOADED', warehouse_id uuid references warehouses(id), shortage integer not null default 0, accepted_at timestamptz, created_at timestamptz not null default now(), user_id uuid references users(id), unique(platform_id,external_id));
create table if not exists public.purchase_order_lines (id uuid primary key default gen_random_uuid(), po_id uuid not null references purchase_orders(id), sku_id uuid not null references skus(id), ordered integer not null, unit_price numeric not null default 0, allocated integer not null default 0, delivered integer not null default 0, unique(po_id,sku_id));
create table if not exists public.po_documents (id uuid primary key default gen_random_uuid(), po_id uuid unique not null references purchase_orders(id), filename text not null, path text not null, sha256 text not null, extracted_json jsonb, confidence numeric, corrected_json jsonb, uploaded_at timestamptz default now());
create table if not exists public.stock_reservations (id uuid primary key default gen_random_uuid(), po_id uuid unique not null references purchase_orders(id), status text default 'ACTIVE', created_at timestamptz default now());
create table if not exists public.appointments (id uuid primary key default gen_random_uuid(), po_id uuid unique not null references purchase_orders(id), appointment_id text, booking_date timestamptz, appointment_at timestamptz, location text, status text default 'PENDING_BOOKING', document_path text);
create table if not exists public.shipments (id uuid primary key default gen_random_uuid(), number text unique not null, po_id uuid not null references purchase_orders(id), source_warehouse_id uuid not null references warehouses(id), destination text not null, truck_number text, driver_name text, driver_phone text, status text default 'PLANNED', planned_dispatch timestamptz, expected_arrival timestamptz, actual_dispatch timestamptz, actual_arrival timestamptz, estimated_cost numeric, actual_cost numeric);
create table if not exists public.shipment_lines (id uuid primary key default gen_random_uuid(), shipment_id uuid not null references shipments(id), po_line_id uuid not null references purchase_order_lines(id), planned integer not null, dispatched integer default 0, delivered integer default 0, unique(shipment_id,po_line_id));
create table if not exists public.shipment_events (id uuid primary key default gen_random_uuid(), shipment_id uuid not null references shipments(id), status text not null, event_at timestamptz default now(), location text, notes text);
create table if not exists public.pods (id uuid primary key default gen_random_uuid(), po_id uuid not null references purchase_orders(id), filename text not null, path text default '', sha256 text unique not null, delivery_at timestamptz, receiver text, confirmed_at timestamptz default now());
create table if not exists public.pod_lines (id uuid primary key default gen_random_uuid(), pod_id uuid not null references pods(id), po_line_id uuid not null references purchase_order_lines(id), confirmed integer not null default 0, short integer not null default 0, damaged integer not null default 0, rejected integer not null default 0, unique(pod_id,po_line_id));
create table if not exists public.invoices (id uuid primary key default gen_random_uuid(), po_id uuid unique not null references purchase_orders(id), number text not null, invoice_date timestamptz not null, amount numeric not null, filename text not null, path text default '', uploaded_at timestamptz default now(), sent_at timestamptz, send_status text default 'PENDING');
create table if not exists public.inventory_movements (id uuid primary key default gen_random_uuid(), type text not null, warehouse_id uuid not null references warehouses(id), sku_id uuid not null references skus(id), quantity integer not null, reference_type text, reference_id uuid, reason text, created_at timestamptz default now(), user_id uuid references users(id));
create table if not exists public.audit_events (id uuid primary key default gen_random_uuid(), user_id uuid references users(id), action text not null, record_type text not null, record_id uuid not null, old_value jsonb, new_value jsonb, reason text, po_id uuid references purchase_orders(id), created_at timestamptz default now());

create or replace function public.add_stock(p_warehouse_id uuid,p_sku_id uuid,p_quantity integer,p_reason text,p_user_id uuid) returns jsonb language plpgsql security definer as $$ declare mid uuid; begin if p_quantity<=0 then raise exception 'quantity must be positive'; end if; insert into inventory_balances(warehouse_id,sku_id,physical) values(p_warehouse_id,p_sku_id,p_quantity) on conflict(warehouse_id,sku_id) do update set physical=inventory_balances.physical+p_quantity; insert into inventory_movements(type,warehouse_id,sku_id,quantity,reason,reference_type,user_id) values('STOCK_ADD',p_warehouse_id,p_sku_id,p_quantity,p_reason,'MANUAL',p_user_id) returning id into mid; return jsonb_build_object('movement_id',mid,'quantity',p_quantity); end $$;
create or replace function public.accept_purchase_order(p_po_id uuid,p_user_id uuid) returns jsonb language plpgsql security definer as $$ declare po record; l record; bal record; threshold integer; reserve integer; shortage integer:=0; result jsonb; begin select * into po from purchase_orders where id=p_po_id for update; if po.id is null or po.warehouse_id is null then raise exception 'Warehouse mapping required'; end if; for l in select * from purchase_order_lines where po_id=p_po_id loop select coalesce(threshold,0) into threshold from warehouse_sku_policies where warehouse_id=po.warehouse_id and sku_id=l.sku_id; select * into bal from inventory_balances where warehouse_id=po.warehouse_id and sku_id=l.sku_id for update; reserve:=least(l.ordered,greatest(0,coalesce(bal.physical,0)-coalesce(bal.blocked,0)-threshold)); shortage:=shortage+(l.ordered-reserve); if reserve>0 then update inventory_balances set blocked=blocked+reserve where id=bal.id; insert into inventory_movements(type,warehouse_id,sku_id,quantity,reference_type,reference_id,user_id) values('RESERVE',po.warehouse_id,l.sku_id,reserve,'PO',p_po_id,p_user_id); update purchase_order_lines set allocated=reserve where id=l.id; end if; end loop; update purchase_orders set status=case when shortage>0 then 'INVENTORY_SHORTAGE' else 'ACCEPTED' end,shortage=shortage,accepted_at=now() where id=p_po_id; insert into stock_reservations(po_id) values(p_po_id) on conflict(po_id) do update set status='ACTIVE'; select to_jsonb(purchase_orders.*) into result from purchase_orders where id=p_po_id; return result; end $$;
create or replace function public.short_close_purchase_order(p_po_id uuid,p_user_id uuid,p_reason text) returns jsonb language plpgsql security definer as $$ declare po record; l record; release_qty integer; result jsonb; begin select * into po from purchase_orders where id=p_po_id for update; for l in select * from purchase_order_lines where po_id=p_po_id loop release_qty:=greatest(0,l.allocated-l.delivered); if release_qty>0 then update inventory_balances set blocked=blocked-release_qty where warehouse_id=po.warehouse_id and sku_id=l.sku_id; insert into inventory_movements(type,warehouse_id,sku_id,quantity,reference_type,reference_id,reason,user_id) values('RELEASE',po.warehouse_id,l.sku_id,release_qty,'SHORT_CLOSE',p_po_id,p_reason,p_user_id); end if; end loop; update purchase_orders set status='SHORT_CLOSED' where id=p_po_id returning to_jsonb(purchase_orders.*) into result; return result; end $$;
create or replace function public.dispatch_shipment(p_shipment_id uuid,p_user_id uuid) returns jsonb language plpgsql security definer as $$ declare sh record; l record; pol record; result jsonb; begin select * into sh from shipments where id=p_shipment_id for update; for l in select * from shipment_lines where shipment_id=p_shipment_id loop select * into pol from purchase_order_lines where id=l.po_line_id; update inventory_balances set blocked=blocked-l.planned,in_transit=in_transit+l.planned where warehouse_id=sh.source_warehouse_id and sku_id=pol.sku_id; insert into inventory_movements(type,warehouse_id,sku_id,quantity,reference_type,reference_id,user_id) values('DISPATCH',sh.source_warehouse_id,pol.sku_id,l.planned,'SHIPMENT',p_shipment_id,p_user_id); update shipment_lines set dispatched=planned where id=l.id; end loop; update shipments set status='IN_TRANSIT',actual_dispatch=now() where id=p_shipment_id returning to_jsonb(shipments.*) into result; return result; end $$;
create or replace function public.confirm_pod(p_po_id uuid,p_sha256 text,p_filename text,p_receiver text,p_lines jsonb,p_user_id uuid) returns jsonb language plpgsql security definer as $$ declare pod_id uuid; item jsonb; pol record; q integer; result jsonb; begin insert into pods(po_id,filename,sha256,receiver,confirmed_at) values(p_po_id,p_filename,p_sha256,p_receiver,now()) returning id into pod_id; for item in select * from jsonb_array_elements(p_lines) loop select * into pol from purchase_order_lines where id=(item->>'poLineId')::uuid; q=coalesce((item->>'confirmed')::integer,0); insert into pod_lines(pod_id,po_line_id,confirmed,short,damaged,rejected) values(pod_id,pol.id,q,coalesce((item->>'short')::integer,0),coalesce((item->>'damaged')::integer,0),coalesce((item->>'rejected')::integer,0)); update inventory_balances set in_transit=in_transit-q where warehouse_id=(select warehouse_id from purchase_orders where id=p_po_id) and sku_id=pol.sku_id; update purchase_order_lines set delivered=delivered+q where id=pol.id; end loop; if not exists(select 1 from purchase_order_lines where po_id=p_po_id and delivered<ordered) then update purchase_orders set status='FULLY_DELIVERED' where id=p_po_id; end if; select to_jsonb(pods.*) into result from pods where id=pod_id; return result; end $$;

alter table public.users enable row level security;
create policy "users can read own profile" on public.users for select using (auth.uid()=id);
alter table public.audit_events enable row level security;
create policy "authenticated users can read audit" on public.audit_events for select to authenticated using (true);
